snippet_css:
:root{
  --bg: #F5F1EA;
  --fg: #0B0B0B;
  --muted: #4D473F;
  --surface: #FFFFFF;
  --border: rgba(11,11,11,.22);
  --accent: #7A5F2A;
  --accent-fg: #F5F1EA;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: linear-gradient(150deg,#E6DFD3,#CBBFA9);
  --media-bg: linear-gradient(150deg,#E6DFD3,#CBBFA9);
  --cta-bg: #EFE7D9;
  --input-bg: #FFFFFF;
  --ok: #1F5C3A;
  --warn: #8E2F1E;
  --font-display: 'Bodoni Moda','Noto Serif TC',serif;
  --font-body: Montserrat,'Noto Sans TC',sans-serif;
  --font-mono: ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

